create extension if not exists pgcrypto;
create table public.tournaments(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,subtitle text,description text,date date not null,start_time time,end_time time,venue_name text,venue_address text,venue_confirmed boolean not null default false,entry_fee numeric(8,2),capacity int not null check(capacity>0),registration_open boolean not null default false,registration_deadline timestamptz,rules jsonb not null default '[]',schedule jsonb not null default '[]',schedule_finalized boolean not null default false,prize_description text,rain_policy text,refund_policy text,contact_email text,status text not null default 'draft' check(status in('draft','registration_open','registration_closed','in_progress','completed','cancelled')),payment_method text not null default 'pay_later' check(payment_method in('free','pay_later','external','stripe')),payment_instructions text,faq jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.registrations(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments on delete cascade,first_name text not null,last_name text not null,email text not null,phone text not null,age int not null,self_rating text not null,ntrp text,utr text,years_playing int,experience text,preferred_division text,notes text,status text not null check(status in('registered','waitlisted','withdrawn','confirmed')),seed int,waiver_accepted boolean not null,rules_accepted boolean not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index one_active_registration_per_email on public.registrations(tournament_id,lower(email)) where status<>'withdrawn';
alter table public.tournaments enable row level security;alter table public.registrations enable row level security;
create policy "published tournaments are public" on public.tournaments for select using(status<>'draft');
create policy "admins manage tournaments" on public.tournaments for all to authenticated using(true) with check(true);
create policy "admins read registrations" on public.registrations for select to authenticated using(true);
create policy "admins manage registrations" on public.registrations for all to authenticated using(true) with check(true);
create or replace function public.register_for_tournament(p_tournament_id uuid,p_registration jsonb) returns table(id uuid,status text) language plpgsql security definer set search_path=public as $$ declare t tournaments; n int; new_status text; new_id uuid; begin select * into t from tournaments where tournaments.id=p_tournament_id for update;if not found then raise exception 'tournament_not_found';end if;if exists(select 1 from registrations r where r.tournament_id=p_tournament_id and lower(r.email)=lower(p_registration->>'email') and r.status<>'withdrawn') then raise exception 'duplicate_registration';end if;select count(*) into n from registrations r where r.tournament_id=p_tournament_id and r.status in('registered','confirmed');if t.registration_open and n<t.capacity then new_status:='registered';else new_status:='waitlisted';end if;insert into registrations(tournament_id,first_name,last_name,email,phone,age,self_rating,ntrp,utr,years_playing,experience,preferred_division,notes,status,waiver_accepted,rules_accepted) values(p_tournament_id,p_registration->>'first_name',p_registration->>'last_name',lower(p_registration->>'email'),p_registration->>'phone',(p_registration->>'age')::int,p_registration->>'self_rating',nullif(p_registration->>'ntrp',''),nullif(p_registration->>'utr',''),nullif(p_registration->>'years_playing','')::int,nullif(p_registration->>'experience',''),nullif(p_registration->>'preferred_division',''),nullif(p_registration->>'notes',''),new_status,true,true) returning registrations.id into new_id;return query select new_id,new_status;end $$;revoke all on function public.register_for_tournament(uuid,jsonb) from public;grant execute on function public.register_for_tournament(uuid,jsonb) to service_role;
insert into public.tournaments(id,slug,name,subtitle,description,date,start_time,venue_address,venue_confirmed,capacity,registration_open,rules,schedule,contact_email,status,payment_method,payment_instructions,faq) values('00000000-0000-0000-0000-000000000001','provo-labor-day-2026','Provo Labor Day Tennis Tournament','Fast matches. Competitive tennis. A great day on the courts.','Fast-paced community tennis is coming to Provo. We''re starting small with 16 players, a fun competitive format, scheduled matches, and a great day of tennis.','2026-09-07','08:00','Provo, Utah',false,16,true,'["Singles","16-player field","Fast timed matches","Four short quarters","One serve","Every point counts","First player to win three quarters wins the match","Sudden-death deciding quarter when necessary"]','[{"time":"8:00 AM","label":"Tournament begins"},{"time":"Morning","label":"Opening matches"},{"time":"Afternoon","label":"Knockout rounds"},{"time":"Late afternoon","label":"Championship"}]','hello@provotennis.com','registration_open','pay_later','Payment instructions will be sent once tournament details are finalized.','[]');
